func TestGetResourcesForPolicyCallback(t *testing.T) {
	providerSchema := *getProviderSchemaResponseFromProviderSchema(&providerSchema{
		ResourceTypes: map[string]*configschema.Block{
			"test_resource": {
				Attributes: map[string]*configschema.Attribute{
					"id": {
						Type:     cty.String,
						Computed: true,
					},
					"name": {
						Type:     cty.String,
						Optional: true,
					},
				},
				BlockTypes: map[string]*configschema.NestedBlock{
					"child": {
						Nesting: configschema.NestingSingle,
						Block: configschema.Block{
							Attributes: map[string]*configschema.Attribute{
								"value": {
									Type:     cty.String,
									Optional: true,
								},
							},
						},
					},
				},
			},
		},
	})

	config := testModuleInline(t, map[string]string{
		"main.tf": `
resource "test_resource" "a" {
  name = "alpha"

  child {
    value = "one"
  }
}

resource "test_resource" "b" {
  name = "beta"

  child {
    value = "two"
  }
}
`,
	})

	state := states.NewState().SyncWrapper()
	state.SetResourceInstanceCurrent(
		mustResourceInstanceAddr("test_resource.a"),
		&states.ResourceInstanceObjectSrc{
			Status:    states.ObjectReady,
			AttrsJSON: []byte(`{"id":"a","name":"alpha","child":{"value":"one"}}`),
		},
		mustProviderConfig(`provider["registry.terraform.io/hashicorp/test"]`),
	)
	state.SetResourceInstanceCurrent(
		mustResourceInstanceAddr("test_resource.b"),
		&states.ResourceInstanceObjectSrc{
			Status:    states.ObjectReady,
			AttrsJSON: []byte(`{"id":"b","name":"beta","child":{"value":"two"}}`),
		},
		mustProviderConfig(`provider["registry.terraform.io/hashicorp/test"]`),
	)
	state.Close()

	ctx := &MockEvalContext{
		StateState:     state,
		ChangesChanges: plans.NewChanges().SyncWrapper(),
		DeferralsState: deferring.NewDeferred(false),
	}

	callback := getResourcesForPolicyCallback(ctx, walkApply, nil, providerSchema, config)

	tests := []struct {
		name        string
		filter      cty.Value
		wantNames   []string
		wantUnknown bool
	}{
		{
			name:        "null filter returns all matching resources",
			filter:      cty.NullVal(cty.DynamicPseudoType),
			wantNames:   []string{"alpha", "beta"},
			wantUnknown: false,
		},
		{
			name: "scalar attribute filter matches a subset",
			filter: cty.ObjectVal(map[string]cty.Value{
				"name": cty.StringVal("alpha"),
			}),
			wantNames:   []string{"alpha"},
			wantUnknown: false,
		},
		{
			name: "nested block filter filter matches a subset",
			filter: cty.ObjectVal(map[string]cty.Value{
				"child": cty.ObjectVal(map[string]cty.Value{
					"value": cty.StringVal("one"),
				}),
			}),
			wantNames:   []string{"alpha"},
			wantUnknown: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var (
				got        []cty.Value
				gotUnknown bool
				gotErr     error
			)

			got, gotUnknown, gotErr = callback(t.Context(), "test_resource", tt.filter)
			if gotErr != nil {
				t.Fatalf("unexpected error: %v", gotErr)
			}
			if gotUnknown != tt.wantUnknown {
				t.Fatalf("wrong unknown result\ngot:  %t\nwant: %t", gotUnknown, tt.wantUnknown)
			}

			gotNames := make([]string, 0, len(got))
			for _, resource := range got {
				gotNames = append(gotNames, resource.GetAttr("name").AsString())
			}
			sort.Strings(gotNames)

			wantNames := append([]string{}, tt.wantNames...)
			sort.Strings(wantNames)
			if diff := cmp.Diff(wantNames, gotNames); diff != "" {
				t.Fatalf("wrong matched resources (-want +got):\n%s", diff)
			}
		})
	}
}

	provider, _, err := getProvider(ctx, actionRef.actionNode.ResolvedProvider)
	if err != nil {
		diags = diags.Append(&hcl.Diagnostic{
			Severity: hcl.DiagError,
			Summary:  "Failed to get provider",
			Detail:   fmt.Sprintf("Failed to get provider: %s", err),
			Subject:  actionRef.actionNode.Config.DeclRange.Ptr(),
		})

		return
	}

	unmarkedConfig, _ := actionVal.UnmarkDeepWithPaths()

	resp := provider.PlanAction(providers.PlanActionRequest{
		ActionType:         actionRef.actionNode.Addr.Action.Type,
		ProposedActionData: unmarkedConfig,
		ClientCapabilities: ctx.ClientCapabilities(),
	})

	// Associate any provider produced diagnostics with the action config block.
	resp.Diagnostics = resp.Diagnostics.InConfigBody(actionRef.actionNode.Config.Body, diagsWith)

	diags = diags.Append(resp.Diagnostics)

	if resp.Deferred != nil {
		if !ctx.Deferrals().DeferralAllowed() {
			diags = diags.Append(deferring.UnexpectedProviderDeferralDiagnostic(actionInst))
			return
		}
		log.Printf("[DEBUG] action instance %s deferred by provider", actionInst)
		deferred = true
		return
	}

	if resp.Diagnostics.HasErrors() {
		return
	}

	ai.ConfigValue = ephemeral.RemoveEphemeralValues(actionVal)
